import { Component, inject, Input } from '@angular/core';
import { ButtonComponent } from 'espd-common/button';
import { DropdownModule } from 'espd-common/dropdown';
import { MessageModule, MessageService } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { Action, ActionList, ActionListSeparator, NoAction, SingleAction } from 'espd-common/layout/actions';

@Component({
	selector: 'espd-table-action-cell',
	templateUrl: './table-action-cell.component.html',
	styleUrls: ['./table-action-cell.component.scss'],
	imports: [
		ButtonComponent,
		DropdownModule,
		IconDirective,
		MessageModule
	]
})
export class TableActionCellComponent {

	private static nextId = 0;

	@Input()
	public actions?: ActionList | SingleAction | NoAction;

	@Input()
	public rowItemName?: string;

	/** An ID to identify this component instance. Used for generating unique IDs in the DOM */
	public id: number = TableActionCellComponent.nextId++;

	private messageService = inject(MessageService);

	public get hasActions(): boolean {
		return this.isSingleAction || this.isActionList;
	}

	public get isActionList(): boolean {
		return this.isActionListType(this.actions) && this.actions.actions.length > 0;
	}

	public get isSingleAction(): boolean {
		return this.actions instanceof SingleAction;
	}

	public get singleAction(): SingleAction {
		return this.actions as SingleAction;
	}

	public get actionList(): ActionList {
		return (this.actions as ActionList);
	}

	public get actionListLabel(): string {
		return this.messageService.evaluate(this.actionList.label);
	}

	public isSeparator(action: Action): boolean {
		return action instanceof ActionListSeparator;
	}

	private isActionListType(actions: ActionList | SingleAction | NoAction | undefined): actions is ActionList {
		return !!actions && this.actionList.actions !== undefined;
	}
}