import { NgTemplateOutlet } from '@angular/common';
import { Component, EventEmitter, Input, OnChanges, Output, TemplateRef } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Page } from 'espd-common/data';
import { MessageConfig, MessageModule } from 'espd-common/i18n';
import { ActionsGenerator, SectionActionsComponent } from 'espd-common/layout/actions';
import { PaginationModule } from 'espd-common/pagination';
import { ObjectUtils } from 'espd-common/utils';
import { PageChangedEvent } from 'ngx-bootstrap/pagination';
import { TableActionCellComponent } from './table-action-cell/table-action-cell.component';
import { TableCellComponent } from './table-cell/table-cell.component';
import { ColumnDefinition, RowItem, SectionConfig, SectionHeaderContent } from './table.model';

@Component({
	selector: 'espd-table',
	templateUrl: './table.component.html',
	styleUrls: ['./table.component.scss'],
	imports: [
		FormsModule,
		MessageModule,
		NgTemplateOutlet,
		PaginationModule,
		SectionActionsComponent,
		TableActionCellComponent,
		TableCellComponent
	]
})
export class TableComponent implements OnChanges {

	private static nextId = 0;

	public readonly id: number;

	@Input()
	public caption?: MessageConfig | string;

	@Input()
	public items?: RowItem[];

	@Input()
	public page?: Page<RowItem>;

	@Input()
	public columns?: ColumnDefinition[];

	@Input()
	public sectionConfig?: SectionConfig;

	@Input()
	public actionsGenerator?: ActionsGenerator;

	@Input()
	public disablePagination = false;

	@Output()
	public readonly pageChanged = new EventEmitter<number>();

	private previousSectionId: unknown = null;

	constructor() {
		this.id = TableComponent.nextId++;
	}

	public get rows(): RowItem[] {
		return this.page?.content ?? this.items ?? [];
	}

	public get tableRows(): RowItem[] {
		this.previousSectionId = null;
		return this.rows;
	}

	public startItem = 0;
	public endItem = 0;

	public ngOnChanges(): void {
		if (this.page) {
			this.startItem = this.page.number * this.page.size + 1;
			this.endItem = this.startItem + this.page.numberOfElements - 1;
		}
	}

	public onPageChanged(event: PageChangedEvent): void {
		this.pageChanged.next(event.page - 1);
	}

	public needsHeader(item: RowItem): boolean {
		if (this.sectionConfig?.sectionIdExtractor) {
			const sectionId = ObjectUtils.extractValue(item, this.sectionConfig.sectionIdExtractor);
			const needsHeader = sectionId !== this.previousSectionId;
			this.previousSectionId = sectionId;
			return needsHeader;
		}
		return false;
	}

	public getHeaderDetails(item: RowItem): SectionHeaderContent {
		if (this.sectionConfig?.sectionIdExtractor) {
			return this.getSectionHeader(this.getSectionId(item));
		}
		return { header: '', sectionId: null };
	}

	public getCellHeaderIds(item: object, colIndex: number): string {
		let headerIds = `table-${this.id}-header-${colIndex}`;

		const sectionId = this.getSectionId(item);
		if (sectionId) {
			return headerIds = `table-${this.id}-section-${sectionId} ${headerIds}`;
		}
		return headerIds;
	}

	private getSectionHeader(sectionId: unknown): SectionHeaderContent {
		const config = this.sectionConfig!;
		if (config.headerTextFn) {
			return { header: config.headerTextFn(sectionId), sectionId };
		} else if (config.headerContentFn) {
			return { ...config.headerContentFn(sectionId), sectionId };
		} else {
			return { header: '', sectionId };
		}
	}

	private getSectionId(item: object): string|number {
		const id = this.sectionConfig?.sectionIdExtractor
			? ObjectUtils.extractValue(item, this.sectionConfig.sectionIdExtractor)
			: null;
		if (!!id && typeof id !== 'string' && typeof id !== 'number') {
			throw new Error('Section ID must be a string or number.');
		} else if (typeof id === 'string') {
			return id.replace(/\s+/g, '-');
		}
		return id as string|number;
	}

	public isTextual(content: string | MessageConfig | TemplateRef<unknown>): content is string | MessageConfig {
		return !!content && (typeof content === 'string' || Object.prototype.hasOwnProperty.call(content, 'key'));
	}

	public isTemplate(content: string | MessageConfig | TemplateRef<unknown>): content is TemplateRef<unknown> {
		return !!content && content instanceof TemplateRef;
	}
}